function home(){const why=[['More time for what matters',['Drag-and-drop course builders','Built-in AI creation and translation tools','Sales and VAT tax handling','Tax filing and affiliate payouts','Assisted migration and custom support']],['Made for the modern learner',['Innovative student dashboard','iOS and Android mobile apps','Drip content','Quizzes and completion certificates']],['Business growth that lasts',['Automated upsells and order bumps','Cross-promotional tools built into dashboard','Coupons and flexible payment options','Global payments and tax support']],['Made to adapt and evolve',['Intuitive 3rd-party app integrations','Embeddable product cards and buy buttons','Developer-friendly tools like APIs and webhooks']]];return layout('home','The future of your education business happens here','Build and sell online courses, coaching, digital downloads, and memberships.',`<section class="hero"><div class="container hero-grid"><div class="reveal"><span class="eyebrow">All-in-one creator commerce</span><h1>The future of your education business happens here</h1><p class="lead">Whatever your expertise—languages, fitness, or coding—LearnForge helps you deliver impactful learning, run a smarter business, and scale worldwide.</p><div class="hero-actions"><a class="btn btn-primary" href="#trial">Start for free</a><a class="btn btn-secondary" href="#pricing">Explore our plans</a></div><div class="mini-proof"><span>✓ Courses</span><span>✓ Coaching</span><span>✓ Downloads</span><span>✓ Memberships</span></div></div><div class="visual-card reveal"><div class="hero-tabs" data-tabs="hero"><button class="tab-btn active" data-tab-target="creator">Your view</button><button class="tab-btn" data-tab-target="student">Your student’s view</button></div><div class="preview active" data-tab-panel="hero:creator">${productVisual('Creator admin preview')}</div><div class="preview" data-tab-panel="hero:student"><div class="student-ui"><div class="ui-top"><span>Student dashboard</span><span>72% complete</span></div><div class="ui-body"><div class="course-hero"><strong>Masterclass: Build with AI</strong><span>Continue lesson 08</span></div><div class="progress"><i></i></div><div class="student-grid"><div><b>Next lesson</b><p>Apply your framework with guided practice.</p></div><div><b>Certificate</b><p>Unlock after final quiz.</p></div></div></div></div></div></div></div></section>${statBar()}${section('One platform. Every knowledge product.','Launch your business around online courses, coaching, digital downloads, memberships—or bundle them together.',cards([['Online Courses','Maximize student engagement with videos, quizzes, drip content, and mobile access.','▶'],['Coaching','Offer one-on-one or group sessions, with easy scheduling and payment management.','◉'],['Digital Downloads','Sell templates, guides, and resources your audience can instantly access and use.','⬇'],['Memberships','Build recurring revenue and stronger community with flexible subscription models.','∞']],4))}<section class="section alt"><div class="container"><div class="section-head reveal"><div><span class="eyebrow">Why choose us</span><h2>Built for creators who want leverage, not limits.</h2></div><p>AI, commerce, learning delivery, taxes, and integrations work together in one creator-first operating system.</p></div><div class="tabs-layout"><div class="feature-tabs reveal" data-tabs="why">${why.map(([h],i)=>`<button class="tab-btn ${i===0?'active':''}" data-tab-target="w${i}">${h}</button>`).join('')}</div><div>${why.map(([h,bullets],i)=>`<div class="tab-panel feature-panel ${i===0?'active':''}" data-tab-panel="why:w${i}"><h3>${h}</h3><ul>${bullets.map(b=>`<li>${b}</li>`).join('')}</ul></div>`).join('')}</div></div></div></section><section class="section"><div class="container split"><div class="reveal"><span class="eyebrow">Global scale</span><h2 style="font-size:clamp(2.3rem,5vw,4.5rem);line-height:.95;letter-spacing:-.06em">Human-led learning, delivered worldwide.</h2><p class="lead">In a world where anyone can ask AI for information, LearnForge powers human-led learning that drives student trust, connection, and results—all at global scale.</p><div class="pill-list"><span class="pill">130+ currencies</span><span class="pill">200+ countries</span><span class="pill">VAT, GST, sales tax</span><span class="pill">Mobile learning</span></div></div><div class="orb-visual reveal"></div></div></section>${section('AI automations that save creator time','Kickstart curriculum, lessons, summaries, sales pages, subtitles, translations, and quizzes—then keep your expertise at the center.',cards([['AI curriculum','Generate a strong first draft for course structure and learning outcomes.','AI'],['AI sales pages','Turn your offer into high-converting copy faster.','✍'],['AI subtitles and translations','Make video lessons more accessible across languages.','◎']],3),'dark')}${testimonialSec('home')}${pricingSec()}${integrationsSec()}${section('Trusted social proof that compounds','Creators use LearnForge to build real relationships, protect margins, and keep control over their education brand.',cards([['Full control','Set your prices, own your audience, and build direct student relationships.','★'],['Revenue engine','Bundle offers, automate upsells, and sell around the clock.','$'],['Peace of mind','Excellent uptime plus built-in tax handling frees you to create.','✓']],3))}${faqSec()}${cta()}`)}
function courses(){return layout('online-courses','Online courses by you. Powered by LearnForge','Create and sell online courses that captivate students and scale revenue.',`${hero('online-courses','Online courses','Online courses by you. Powered by LearnForge.','Create and sell online courses that captivate students, scale revenue, and move your business forward—without the tech headache.')}${statBar()}${section('Keep students engaged from first lesson to finish line','Courses feel premium on every device, with motivation mechanics that help students keep progressing.',cards([['On-the-go learning','Let students take your course anywhere with offline access on top-rated iOS and Android mobile apps.','📱'],['Meaningful engagement','Motivate students and drive progress with graded quizzes, certificates, drip content, and more.','🏆'],['Conversion boosters','Reach the right people using marketing features like student referrals and upsells.','↗']],3),'alt')}${section('Build faster with intuitive creation tools','Drag, drop, customize, and use AI as a time-saving partner for creation and localization.',cards([['Intuitive course builder','Drag-and-drop builder makes it easy to create and customize. Rearrange and add content blocks with ease.','▦'],['Powered by AI','Kickstart ideas, draft content, create sales pages, transcribe and translate video subtitles in no time.','AI'],['Make it yours','Advanced customizations, custom domain, and white-label website make your course totally yours.','◆']],3))}<section class="section alt"><div class="container"><div class="demo-box reveal active"><button class="demo-toggle">Interactive product demo preview <span>Toggle</span></button><div class="demo-content"><div class="split"><div>${productVisual('Course builder demo')}</div><div><h3>See the course engine in action</h3><p class="muted">Preview curriculum blocks, sales pages, student progress, checkout, and engagement tools in one focused workspace.</p><div class="pill-list"><span class="pill">Videos</span><span class="pill">Quizzes</span><span class="pill">Drip content</span><span class="pill">Certificates</span></div></div></div></div></div></div></section>${section('Sales hub that handles the hard parts','Launch internationally with payments, tax support, fraud protection, and flexible student checkout options.',cards([['Easy payments','Built-in checkout with fraud protection, tax-inclusive pricing, flexible payout options, and 130+ currencies across 200+ countries.','💳'],['Less tax complexity','We calculate, collect, and remit sales taxes, VAT, and GST on your behalf.','%'],['Pay their way','Students choose PayPal, Apple Pay, Google Pay, Afterpay, or Klarna.','✓']],3))}${integrationsSec()}${testimonialSec('courses')}${section('Tools that power growth','Create, host, manage, and sell from one platform with AI and developer-friendly extensions.',`<div class="grid grid-4">${['Courses','Digital Downloads','Coaching','Community','Live sessions','Quizzes','AI curriculum','AI lessons','AI lesson summaries','AI sales pages','AI subtitles','AI translations','AI quizzes','Unlimited students','Unlimited videos','Embedded media','Downloadable files','Drip content','Course compliance','Email marketing','Custom domain','Sales analytics','External integrations','Public API','Webhooks','Memberships','Bundles','Subscriptions','Payment options','Tax handling','Upsells','Order bump'].map(x=>`<div class="card reveal"><h3>${x}</h3></div>`).join('')}</div>`,'dark')}${cta()}${faqSec([['How quickly can I launch an online course?','Many creators launch in days using the drag-and-drop builder, AI drafting tools, and customizable templates.'],['Can I sell courses with downloads or coaching?','Yes. Bundle courses with downloads, coaching, communities, memberships, subscriptions, upsells, and order bumps.'],...faqs.slice(1,3)])}`)}
