ection('Supported file types','Sell the practical resources your audience already wants to use.',`<div class="grid grid-3 file-grid">${['Design files','Spreadsheets','Ebooks','Email templates','Lesson plans','Asset libraries'].map(x=>`<article class="card reveal"><div class="icon">⬇</div><h3>${x}</h3></article>`).join('')}</div>`)}${cta()}${faqSec([['What can I sell as a digital download?','Sell design files, spreadsheets, ebooks, email templates, lesson plans, asset libraries, guides, checklists, and more.'],['Can downloads be used as lead magnets?','Yes. Downloads work beautifully as free lead magnets, paid entry offers, course bonuses, and checkout upsells.'],...faqs.slice(0,2)])}`)}
function memberships(){return layout('memberships','Revenue on repeat','Create, sell, and manage memberships on LearnForge.',`${hero('memberships','Memberships','Revenue on repeat','Create, sell, and manage memberships on LearnForge. Unlock a new way to earn recurring revenue. Easy for both you and your students to manage.')}${section('Why offer memberships?','Recurring products create predictable revenue, deeper customer relationships, and stronger student outcomes.',cards([['43% higher lifetime value','Membership models can increase customer lifetime value while reducing constant launch pressure.','43%'],['Build subscription tiers','Create flexible tiers for content access, community benefits, coaching, downloads, and bundles.','∞'],['A seamless student experience','Students manage subscriptions, access content, and keep learning from one intuitive dashboard.','✓']],3),'alt')}${section('Management features for recurring growth','Run your membership with the same checkout, tax, learning, analytics, and automation backbone as every LearnForge product.',cards([['Tier controls','Package benefits by level and evolve your offer over time.','▤'],['Subscriber insights','Track members, engagement, churn signals, revenue, and product performance.','📈'],['Content scheduling','Release lessons, resources, and community prompts at the right cadence.','⏱']],3))}${pricingSec()}${section('Resources for successful membership sites','Use proven playbooks to shape your offer, pricing, retention, and launch strategy.',`<div class="grid grid-3">${[['Build a powerful membership product','Learn about the Membership product and how to build a powerful tier to earn more revenue.'],['10 tips for a successful membership site','How to start a successful membership site generating consistent monthly income.'],['Case study: Building a successful membership site','One creator shares how she turned her membership into a profitable business.']].map(([h,p])=>`<article class="card resource-card reveal"><span class="eyebrow">Resource</span><h3>${h}</h3><p>${p}</p><a class="btn btn-secondary" href="#">Read more</a></article>`).join('')}</div>`,'dark')}${integrationsSec()}${testimonialSec('memberships')}${cta()}`)}
function coaching(){return layout('coaching','The best online coaching platform to support your audience','Add more value with professional one-on-one or small group coaching.',`${hero('coaching','Coaching','The best online coaching platform to support your audience','Add more value to your online business through professional one-on-one or small group coaching.')}${statBar()}${section('Create your coaching business in three steps','Set up a professional coaching product that sells solo or alongside courses, downloads, and memberships.',cards([['Create your coaching product','Create, sell, and manage all aspects of your coaching business. Sell solo or alongside courses and downloads.','1'],['Upload your content','Customize content based on audience needs. Create milestones, schedule meetings, set up video calls, send messages and files.','2'],['Customize and sell','Offer a professional learning experience with easy-to-use, customizable sales pages.','3']],3),'alt')}${section('Everything coaches need to grow with care','Deliver high-touch support while LearnForge handles payments, customization, scale, and client fit.',cards([['Payment processing and more','Automated payments, fraud protection, tax-inclusive pricing, global currency conversion, and 0% transaction fees on Pro and Business plans.','💳'],['A personal touch','Drag-and-drop builder and customizable templates help personalize products, assignments, appointments, and client goals.','♡'],['Scale made easy','Average coaching price over $200. Built-in upsell and order bump features maximize earning potential.','↗'],['Coach with care','Customizable intake block and page editor give you control over who you onboard as a client.','✓']],4))}${section('Coaching spotlight','Creators use LearnForge to transform expertise into scalable coaching experiences.',cards([['Kinobody Fitness','Greg O\'Gallagher expanded from personal training to online fitness courses.','💪'],['Tailored Tutors','Making high-quality tutoring services available from anywhere with LearnForge.','✎'],['UAV Coach','40,000+ students trained for FAA drone certification exams.','✈']],3),'dark')}${section('Resources for coaches','Build your coaching offer with clear outcomes, smooth onboarding, and scalable learning assets.',cards([['Offer design','Shape one-on-one, cohort, and hybrid coaching products around client goals.','◎'],['Client onboarding','Use intake blocks, milestones, scheduling, messages, and files to keep momentum high.','→'],['Scale systems','Pair coaching with courses, downloads, and memberships to serve more people without losing quality.','▣']],3))}${integrationsSec()}${testimonialSec('coaching')}${cta()}${faqSec([['Can I offer one-on-one and group coaching?','Yes. Create one-on-one, small group, cohort, and hybrid coaching offers with scheduling, messaging, files, and milestones.'],['Can coaching be sold with courses?','Yes. Coaching can be sold solo or bundled alongside courses, digital downloads, communities, and memberships.'],...faqs.slice(1,3)])}`)}
