function layout(page,title,desc,body){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} | LearnForge</title><meta name="description" content="${desc}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"></head><body>${header(page)}${body}${footer()}<script src="script.js"></script></body></html>`}
function header(page){return `<nav class="nav"><div class="container nav-inner"><a class="brand" href="index.html"><span class="brand-mark"></span><span>LearnForge</span></a><div class="nav-links">${nav.map(([n,h,id])=>`<a class="${page===id?'active':''}" href="${h}">${n}</a>`).join('')}</div><div class="nav-actions"><a class="btn btn-secondary" href="index.html#pricing">Explore plans</a><a class="btn btn-primary" href="#trial">Start Free Trial</a><button class="mobile-toggle" aria-label="Open navigation">☰</button></div></div></nav>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-mark"></span><span>LearnForge</span></a><p class="muted">The all-in-one platform for creators, experts, and businesses serious about online education.</p></div>${[['Explore',['Pricing','Example Schools','Product Demo']],['Company',['About us','Careers','Press','Partners','Newsletter']],['Support',['Help Center','Blog','Pricing','House Rules','Content Guidelines']],['Legal',['Privacy Policy','Terms of Use','Cookies Policy','Ethics Line','Accessibility']]].map(([h,links])=>`<div><h4>${h}</h4>${links.map(l=>`<a href="#">${l}</a>`).join('')}</div>`).join('')}</div><div class="footer-bottom">© 2026 LearnForge. Built for human-led learning at global scale.</div></div></footer>`}
function hero(page,eyebrow,title,subtitle,extra=''){return `<section class="hero product"><div class="container hero-grid"><div class="reveal"><span class="eyebrow">✦ ${eyebrow}</span><h1>${title}</h1><p class="lead">${subtitle}</p><div class="hero-actions"><a class="btn btn-primary" href="#trial">Start Free Trial</a><a class="btn btn-secondary" href="#features">See features</a></div><div class="mini-proof"><span>✓ 7-day free trial</span><span>✓ Global payments</span><span>✓ No tech headache</span></div></div><div class="visual-card reveal">${extra||productVisual(title)}</div></div></section>`}
function productVisual(label){return `<div class="admin-ui"><div class="ui-top"><span>${label.split('.')[0]}</span><span>Live</span></div><div class="ui-body"><div class="side"><span></span><span></span><span></span><span></span></div><div class="main-pane"><div class="metric-row"><div class="metric"><b>98%</b><br><small>Uptime</small></div><div class="metric"><b>130+</b><br><small>Currencies</small></div><div class="metric"><b>AI</b><br><small>Assisted</small></div></div><div class="chart"></div><div class="lesson-list"><span></span><span></span><span></span></div></div></div></div>`}
function statBar(){return `<section class="stats-bar"><div class="container"><div class="stats-wrap reveal">${stats.map(([n,t])=>`<div class="stat"><b>${n}</b><span>${t}</span></div>`).join('')}</div></div></section>`}
function section(title,lead,content,cls=''){return `<section id="features" class="section ${cls}"><div class="container"><div class="section-head reveal"><div><span class="eyebrow">LearnForge</span><h2>${title}</h2></div>${lead?`<p>${lead}</p>`:''}</div>${content}</div></section>`}
function cards(items,cols=3){return `<div class="grid grid-${cols}">${items.map(([h,p,i='✦'])=>`<article class="card reveal"><div class="icon">${i}</div><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`}
function integrationsSec(){return section('Connect the tools your business already trusts','Stripe, Zapier, Mailchimp, PayPal, Calendly, and more fit naturally into your creator stack.',`<div class="integrations reveal">${integrations.map(x=>`<div class="logo-tile">${x}</div>`).join('')}</div>`,'alt')}
function testimonialSec(page){return section('Creators are building durable businesses','Every LearnForge product is backed by the same global infrastructure, tax handling, uptime, and creator-first control.',`<div class="carousel reveal" data-carousel="${page}"><div class="carousel-track">${testimonials.map(([person,kicker,quote],i)=>`<article class="testimonial ${i===0?'active':''}"><div class="eyebrow">${kicker}</div><p class="quote">“${quote}”</p><div class="person">${person}</div></article>`).join('')}</div><div class="carousel-controls"><button class="ctrl" data-prev aria-label="Previous testimonial">←</button><button class="ctrl" data-next aria-label="Next testimonial">→</button></div></div>`)}
function faqSec(list=faqs){return section('Frequently asked questions','Fast answers for creators comparing platforms, pricing, and product options.',`<div class="faq reveal">${list.map(([q,a],i)=>`<div class="faq-item ${i===0?'active':''}"><button class="faq-q">${q}</button><div class="faq-a">${a}</div></div>`).join('')}</div>`,'alt')}
